# ---------------------------------------------------------------------------
# Row-Level Security: the second tenant-isolation layer.
# Every tenant table only shows and accepts rows whose company_id equals the
# transaction setting app.company_id. FORCE makes the policies apply to the
# table owner too; only a superuser or a BYPASSRLS role is exempt, and the
# application must connect as a role that is neither (checked at start-up).
# ---------------------------------------------------------------------------
TENANT_TABLES = (
    "users", "refresh_tokens", "invites", "sessions", "events", "tasks", "calendar_events",
    "calendar_attendees", "documents", "ai_usage", "meeting_requests", "messages",
    "notifications", "email_log",
)
APP_ROLE = "office_app"

CURRENT_COMPANY = """
CREATE FUNCTION app_current_company() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT NULLIF(current_setting('app.company_id', true), '')::uuid
$$;
"""

# Lookups needed before the company is known (login, join). SECURITY DEFINER runs
# them as the owner; they return only the columns the auth flow needs.
LOOKUPS = """
CREATE FUNCTION auth_find_user(p_email text)
RETURNS TABLE (id uuid, company_id uuid, password_hash text, role text, status text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
    SELECT u.id, u.company_id, u.password_hash, u.role, u.status
    FROM users u WHERE lower(u.email) = lower(p_email)
$$;

CREATE FUNCTION auth_email_taken(p_email text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
    SELECT EXISTS (SELECT 1 FROM users u WHERE lower(u.email) = lower(p_email))
$$;

CREATE FUNCTION auth_company_by_code(p_code text) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
    SELECT c.id FROM companies c WHERE c.join_code = upper(p_code)
$$;

CREATE FUNCTION auth_find_invite(p_hash text)
RETURNS TABLE (id uuid, company_id uuid, email text, expires_at timestamptz, used_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
    SELECT i.id, i.company_id, i.email, i.expires_at, i.used_at
    FROM invites i WHERE i.token_hash = p_hash
$$;
"""
FUNCTIONS = ("app_current_company()", "auth_find_user(text)", "auth_email_taken(text)",
             "auth_company_by_code(text)", "auth_find_invite(text)")


def _enable_rls() -> None:
    op.execute(CURRENT_COMPANY)
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(f"CREATE POLICY tenant_isolation ON {table} "
                   f"USING (company_id = app_current_company()) "
                   f"WITH CHECK (company_id = app_current_company())")
    op.execute("ALTER TABLE companies ENABLE ROW LEVEL SECURITY")
    op.execute("ALTER TABLE companies FORCE ROW LEVEL SECURITY")
    op.execute("CREATE POLICY tenant_isolation ON companies "
               "USING (id = app_current_company()) WITH CHECK (id = app_current_company())")
    op.execute(LOOKUPS)
    for function in FUNCTIONS:
        op.execute(f"REVOKE ALL ON FUNCTION {function} FROM PUBLIC")
    # grant to the application role when it already exists (scripts/create_app_role.py
    # grants again, so the order of the two steps does not matter)
    op.execute(f"""
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{APP_ROLE}') THEN
        GRANT USAGE ON SCHEMA public TO {APP_ROLE};
        GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO {APP_ROLE};
        REVOKE ALL ON alembic_version FROM {APP_ROLE};
        GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {APP_ROLE};
        GRANT EXECUTE ON FUNCTION {", ".join(FUNCTIONS)} TO {APP_ROLE};
    END IF;
END $$;
""")


def _disable_rls() -> None:
    for function in FUNCTIONS[1:]:
        op.execute(f"DROP FUNCTION IF EXISTS {function}")
    for table in TENANT_TABLES + ("companies",):
        op.execute(f"DROP POLICY IF EXISTS tenant_isolation ON {table}")
    op.execute("DROP FUNCTION IF EXISTS app_current_company()")


def upgrade() -> None:
    _create_tables()
    _enable_rls()


def downgrade() -> None:
    _disable_rls()
    _drop_tables()
